109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
112	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
113	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
114	        }
115	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
116	        if (sharesHousehold) {
117	            owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getAddress()));
118	        }
119	        // All duplicate detection is consolidated into the single derived identity key: reject only
120	        // when the new owner's whole identity key (telephone|email|householdId) matches an existing one.
121	        if (this.clinicService.isIdentityKeyInUse(owner)) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        this.clinicService.saveOwner(owner);
128	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
129	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
130	            ownerMapper.formatMembershipLevel(owner));
